function gainLocked(t){return !!(t.locked||(p.masterFaderLock&&!(p.unlockedFaders||[]).includes(t.id)));}
function lockIcon(locked){return `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="${locked?'M8 10V6a4 4 0 018 0v4':'M8 10V6a4 4 0 018 0'}"/><path d="M12 14v3"/></svg>`;}
function channelColor(name){const n=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const has=words=>words.some(w=>n.includes(w));if(n==='master')return '#89acf2';if(has(['bateria','drum','kick','snare','cymbal','tom ']))return '#dc938a';if(has(['percuss','perc','shaker','tambour']))return '#d0ad74';if(has(['baixo','bass']))return '#88b9a0';if(has(['guit','violao','acoustic']))return '#83b4db';if(has(['piano','tecla','keys','keyboard','organ','synth','pad']))return '#b29cda';if(has(['voz','vocal','choir','backing','coro']))return '#81bdc8';if(has(['click','guia','guide','metro']))return '#d0ad74';let h=0;for(let i=0;i<n.length;i++)h=(31*h+n.charCodeAt(i))|0;return ['#81bdc8','#b29cda','#d0ad74','#88b9a0','#dc938a','#89acf2'][(h%6+6)%6];}
function strip(t,master=false,kind='tracks'){const color=validColor(t.color||channelColor(t.name)),isGroup=kind!=='tracks',channel=master?'master':isGroup?kind+':'+t.id:t.id,locked=master?p.masterFaderLock:gainLocked(t);return '<article class="strip '+(master?'master':'')+'" style="--channel:'+color+'" data-strip="'+channel+'"><button class="fader-lock" data-lock="'+channel+'" aria-label="'+(master?'Bloquear todos os faders':'Cadeado '+esc(t.name))+'" aria-pressed="'+locked+'">'+lockIcon(locked)+'</button><div class="name" '+(!master&&!isGroup?'draggable="true"':'')+'>'+esc(t.name)+'</div><small>'+ (isGroup?'OUTPUT':'PAN · <span id="pan-'+channel+'">'+(t.pan===0?'C':t.pan<0?'L':'R')+'</span>')+'</small>'+(isGroup?'<button class="group-route" data-group-edit="'+kind+'">'+(kind==='dcas'?'DCA · EDITAR':esc(t.route||'MASTER'))+'</button>':'<div class="pan-control" style="--angle:'+((t.pan||0)*135)+'deg"><div class="knob-face"><i></i></div><input data-pan="'+channel+'" aria-label="Pan '+esc(t.name)+'" type="range" min="-1" max="1" step=".01" value="'+(t.pan||0)+'"></div>')+'<div class="sm">'+(!master&&!isGroup?'<button data-solo="'+channel+'" class="'+(t.solo?'active':'')+'" aria-label="Solo '+esc(t.name)+'">S</button>':'')+'<button data-mute="'+channel+'" class="'+(t.mute?'active':'')+'" aria-label="Mute '+esc(t.name)+'">M</button></div><button class="zero" data-db="'+channel+'">'+dbText(t.db)+' dB</button><div class="fader-area"><div class="scale">'+['+10','+5','0','−5','−10','−20','−40','−∞'].map(x=>'<span>'+x+'</span>').join('')+'</div><input class="fader" data-fader="'+channel+'" type="range" min="0" max="1000" step="1" value="'+dbToFader(t.db)+'" aria-label="Volume '+esc(t.name)+'"><div class="meter"><i id="meter-'+channel+'"></i></div></div><button data-zero="'+channel+'">0dB</button>'+(!master&&!isGroup?'<button data-track-route="'+t.id+'">'+esc(p.buses.find(g=>g.id===t.route)?.name||t.route||'MASTER')+'</button>':master?'<small>OUT 1–2</small>':'')+'</article>';}
function groupStrip(g,kind){return strip({...g,pan:0,color:kind==='dcas'?'#d0ad74':'#b29cda'},false,kind);}
function channel(id){if(id==='master')return {ref:p,master:true};const [kind,key]=id.split(':');return {ref:key?p[kind]?.find(g=>g.id===key):p.tracks.find(t=>t.id===id),kind:key?kind:'tracks'};}
function dbToFader(db){return Math.round(dbToPosition(db)*1000);}
function faderToDb(v){return positionToDb(v/1000);}
function setDb(id,value){const c=channel(id);if(!c.ref||(c.master?p.masterFaderLock:gainLocked(c.ref)))return;const db=Math.max(-80,Math.min(10,value));if(c.master)p.master=db;else c.ref.db=db;engine.updateMix();persist();const f=document.querySelector('[data-fader="'+id+'"]'),b=document.querySelector('[data-db="'+id+'"]');if(f)f.value=dbToFader(db);if(b)b.textContent=dbText(db)+' dB';}
