 listen('[data-lock]','click',(_,el)=>{const c=channel(el.dataset.lock);if(c.master){p.masterFaderLock=!p.masterFaderLock;p.unlockedFaders=[];}else{const t=c.ref,was=gainLocked(t);t.locked=!was;p.unlockedFaders=(p.unlockedFaders||[]).filter(x=>x!==t.id);if(was&&p.masterFaderLock)p.unlockedFaders.push(t.id);}persist();render();});
