 const pan=(el,v)=>{const c=channel(el.dataset.pan);if(c.master?p.masterFaderLock:gainLocked(c.ref)){el.value=c.master?p.masterPan:c.ref.pan;return;}v=Math.max(-1,Math.min(1,v));if(c.master)p.masterPan=v;else c.ref.pan=v;el.value=v;el.parentElement.style.setProperty('--angle',v*135+'deg');const label=document.getElementById('pan-'+el.dataset.pan);if(label)label.textContent=Math.abs(v)<.05?'C':v<0?'L':'R';engine.updateMix();persist();};
 listen('[data-pan]','input',(_,el)=>pan(el,+el.value));listen('[data-pan]','dblclick',(_,el)=>pan(el,0));listen('[data-pan]','pointerdown',(event,el)=>{if(el.disabled)return;event.preventDefault();el.setPointerCapture(event.pointerId);const move=e=>{const r=el.getBoundingClientRect();let angle=Math.atan2(e.clientX-r.left-r.width/2,-(e.clientY-r.top-r.height/2))*180/Math.PI;pan(el,Math.max(-135,Math.min(135,angle))/135);};move(event);el.onpointermove=move;el.onpointerup=()=>{el.onpointermove=null;};el.onpointercancel=()=>{el.onpointermove=null;};});
