  let dragged;listen('.name[draggable]','dragstart',(e,el)=>{dragged=el.parentElement.dataset.strip;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.setDragImage(el.parentElement,60,30);el.parentElement.classList.add('dragging');});listen('.strip','dragover',e=>e.preventDefault());listen('.strip','drop',(e,el)=>{e.preventDefault();reorder(dragged,el.dataset.strip);});listen('.name','dragend',()=>document.querySelectorAll('.dragging').forEach(x=>x.classList.remove('dragging')));
  // Pointer drag uses the full card as a floating preview on touch devices.
