$('#files').onchange=async e=>{const files=[...e.target.files].filter(f=>e.target!==$('#folderFiles')||/\.(wav|flac|mp3|m4a|aac|ogg|opus)$/i.test(f.name));e.target.value='';if(!files.length||loading)return;if(files.length+(importTarget?.tracks.length||0)>64){notify('Limite de 64 faixas por projeto.');return;}engine.pause();loading=true;const project=importTarget||newProject(files[0].webkitRelativePath?.split('/')[0]||files[0].name.replace(/\.[^.]+$/,''));project.order??=projects.length;if(!importTarget)projects.push(project);p=project;engine.project=p;engine.ready=false;render();let imported=0;const failures=[];try{await navigator.storage?.persist?.().catch(()=>{});for(let i=0;i<files.length;i++){const f=files[i],tid=id(),report=stage=>importProgress(i+1,files.length,f.name,stage);report('Lendo arquivo…');try{const estimate=await navigator.storage?.estimate?.();if(estimate?.quota&&estimate.quota-estimate.usage<f.size)throw Error('Não há espaço suficiente no armazenamento deste navegador. Libere espaço e tente novamente.');const source=await sourceFor(f,tid,b=>engine.decode(b),report),peaks=await analyzeSource(source,report);report('Salvando no navegador…');await DB.putAudio(tid,f);p.tracks.push({id:tid,name:f.name.replace(/\.[^.]+$/,''),duration:source.duration,db:0,pan:0,mute:false,solo:false,speed:100,pitch:0,route:'master',peaks,peakVersion:3});p.speedTracks?.push(tid);imported++;await DB.saveProject(p);}catch(error){console.error(error);await clearAudioCache(tid).catch(()=>{});failures.push(`${f.name}: ${error.name==='QuotaExceededError'?'Armazenamento do navegador cheio.':error.message||'Não foi possível importar.'}`);}}}finally{loading=false;finishProgress();await choose(p);notify(`${imported} de ${files.length} tracks importadas.`);if(!failures.length&&imported)editProject();if(failures.length)show(head('Arquivos não importados')+`<p>As tracks importadas foram preservadas. Confira os arquivos e o espaço disponível antes de tentar novamente.</p>${failures.map(x=>`<p>${esc(x)}</p>`).join('')}`);}};
$('#backupFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||loading)return;loading=true;engine.pause();render();try{importProgress(0,0,file.name,'Restaurando backup…');const project=await DB.importBackup(file,(i,n,name)=>importProgress(i,n,name,'Restaurando áudio…'));project.order=projects.length;projects.push(project);loading=false;await choose(project);}catch(err){fail(err);}finally{loading=false;finishProgress();render();}};
function editProject(){show(head('Editar projeto')+`<div class="stack"><label>Nome<input id="projectName" value="${esc(p.name)}"></label><label>Tom<input id="projectKey" value="${esc(p.key)}" placeholder="Ex.: E ou F#"></label><label>Imagem do projeto<input id="artwork" type="file" accept="image/*"></label><button id="clearArt">Remover imagem</button><button id="addTracks">Adicionar tracks</button><p class="muted">Ordem das tracks</p>${p.tracks.map((t,i)=>`<div class="row"><span class="spacer">${esc(t.name)}</span><input type="color" aria-label="Cor de ${esc(t.name)}" data-track-color="${t.id}" value="${validColor(t.color||channelColor(t.name))}"><button data-remove-track="${t.id}" aria-label="Remover ${esc(t.name)}">−</button><button data-up="${i}" aria-label="Subir ${esc(t.name)}">↑</button><button data-down="${i}" aria-label="Descer ${esc(t.name)}">↓</button></div>`).join('')}<div class="row"><button id="projectEarlier">← Antecipar projeto</button><button id="projectLater">Adiar projeto →</button></div><div class="actions"><button id="deleteProject" class="danger">Excluir projeto</button><button id="saveEdit" class="primary">Salvar</button></div></div>`);listen('[data-track-color]','input',(_,el)=>{p.tracks.find(t=>t.id===el.dataset.trackColor).color=el.value;persist();});listen('[data-remove-track]','click',async(_,el)=>{if(!confirm('Remover a faixa deste projeto? O arquivo original será preservado.'))return;if(p.tracks.length===1){notify('O projeto precisa de pelo menos uma faixa. Exclua o projeto para remover a última.');return;}p.tracks=p.tracks.filter(t=>t.id!==el.dataset.removeTrack);for(const g of p.dcas)g.members=g.members.filter(id=>id!==el.dataset.removeTrack);persist();await engine.load(p);editProject();render();});$('#projectEarlier').onclick=()=>moveProject(p.id,-1);$('#projectLater').onclick=()=>moveProject(p.id,1);let art=p.art;$('#artwork').onchange=async e=>{const file=e.target.files[0];if(!file)return;const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();const c=document.createElement('canvas');c.width=640;c.height=360;c.getContext('2d').drawImage(img,0,0,640,360);art=c.toDataURL('image/jpeg',.8);}finally{URL.revokeObjectURL(url);}};$('#clearArt').onclick=()=>{art=null;notify('Imagem será removida ao salvar.');};$('#saveEdit').onclick=()=>{p.name=$('#projectName').value.trim()||p.name;p.key=$('#projectKey').value.trim();p.keyAnalyzed=!!p.key;p.art=art;persist();modal.close();render();};$('#addTracks').onclick=()=>{modal.close();startImport(p);};listen('[data-up],[data-down]','click',(_,el)=>{const up=el.dataset.up!==undefined,i=+(up?el.dataset.up:el.dataset.down),j=i+(up?-1:1);if(j>=0&&j<p.tracks.length){[p.tracks[i],p.tracks[j]]=[p.tracks[j],p.tracks[i]];persist();editProject();}});$('#deleteProject').onclick=async()=>{if(!confirm(`Excluir ${p.name} e as cópias de áudio deste navegador? Os arquivos originais permanecem intactos.`))return;engine.stop();await DB.deleteProject(p);projects=projects.filter(x=>x!==p);p=null;engine.project=null;modal.close();render();};}
$('#menu').onclick=()=>{show(`<div class="drawer-main"><button data-close class="close">Fechar</button><div class="drawer-brand"><img src="assets/logo.png" alt="Logo ATMyTrack"><h2>AT<span>My</span>Track</h2></div><button data-nav="projects">▦　Projetos</button><button data-nav="tuner">♫　Afinador</button></div><div class="bottom"><button data-nav="support">◇　DEIXE SUA MARCA</button><button data-nav="help">?　Central de dúvidas</button></div>`,true);listen('[data-nav]','click',(_,el)=>navigate(el.dataset.nav));};
function navigate(next){window.scrollTo(0,0);modal.close();tuner.stop();if(next==='tuner'){engine.pause();pad.stop();}screen=next;history.pushState({screen:next},'',next==='projects'?'#projetos':'#'+next);render();}
addEventListener('popstate',e=>{window.scrollTo(0,0);tuner.stop();screen=e.state?.screen||'projects';render();});

function dsp(kind){const speed=kind==='speed',title=speed?'VELOCIDADE':'TOM',value=speed?p.speed:p.pitch,selected=new Set((speed?p.speedTracks:p.pitchTracks)??p.tracks.filter(t=>speed||!/click|clk|guide|guia|drum|bateria|perc/i.test(t.name)).map(t=>t.id));show(head(title)+(!speed?'<div class="row"><label>Tom original<select id="pitchOrigin">'+NOTES.map(n=>'<option '+(keyParts(p.key)?.note===keyParts(n).note?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>Destino<select id="pitchTarget">'+NOTES.map(n=>'<option '+(keyParts(targetKey(p))?.note===keyParts(n).note?'selected':'')+'>'+n+'</option>').join('')+'</select></label></div>':'')+`<div class="large-value" id="dspValue">${value}${speed?'%':''}</div><input id="dspSlider" aria-label="${title}" type="range" style="width:100%" min="${speed?50:-12}" max="${speed?200:12}" step="1" value="${value}"><div class="row between"><button id="minus">−</button><span>${speed?'50% a 200% · tom preservado':'−12 a +12 semitons'}</span><button id="plus">＋</button></div><div class="presets">${(speed?[50,75,80,90,100,110,125,150,200]:[-12,-5,-2,-1,0,1,2,5,12]).map(v=>`<button data-preset="${v}">${v===(speed?100:0)?'Original':v+(speed?'%':'')}</button>`).join('')}</div><p class="footer">${speed?'Todas as tracks é o modo recomendado para preservar sincronização.':'Seleção independente da velocidade.'}</p><div class="row"><button id="allTracks">Selecionar todas</button><button id="noTracks">Limpar seleção</button></div><div class="track-list">${p.tracks.map(t=>`<label class="check"><input type="checkbox" data-select="${t.id}" ${selected.has(t.id)?'checked':''}>${esc(t.name)}</label>`).join('')}</div><div class="actions"><button id="resetDsp">${speed?'Reset 100%':'Tom original'}</button><button id="applyDsp" class="primary">Aplicar</button></div>`);
  const update=v=>{$('#dspSlider').value=v;$('#dspValue').textContent=$('#dspSlider').value+(speed?'%':'');};if(!speed){$('#pitchTarget').onchange=()=>update(transpose($('#pitchOrigin').value,$('#pitchTarget').value));$('#pitchOrigin').onchange=()=>update(transpose($('#pitchOrigin').value,$('#pitchTarget').value));}$('#dspSlider').oninput=e=>update(e.target.value);$('#minus').onclick=()=>update(+$ ('#dspSlider').value-1);$('#plus').onclick=()=>update(+$ ('#dspSlider').value+1);listen('[data-preset]','click',(_,el)=>update(el.dataset.preset));$('#allTracks').onclick=()=>document.querySelectorAll('[data-select]').forEach(x=>x.checked=true);$('#noTracks').onclick=()=>document.querySelectorAll('[data-select]').forEach(x=>x.checked=false);
  const apply=async v=>{const ids=[...document.querySelectorAll('[data-select]:checked')].map(x=>x.dataset.select);if(speed&&v!==100&&ids.length&&ids.length!==p.tracks.length&&!confirm('Tracks com velocidades diferentes podem perder sincronização entre si. Continuar?'))return;const playing=engine.playing,oldRate=globalRate(p),musical=engine.current()*oldRate;engine.pause();if(!speed&&$('#pitchOrigin'))p.key=$('#pitchOrigin').value+(keyParts(p.key)?.minor?'m':'');p[kind]=v;p[kind+'Tracks']=ids;for(const t of p.tracks){if(speed)t.speed=ids.includes(t.id)?v:100;else t.pitch=ids.includes(t.id)?v:0;}engine.position=musical/globalRate(p);persist();if(pad.crossOwned){const k=keyParts(targetKey(p));if(k)pad.transition(k,3).catch(fail);}modal.close();render();if(playing){notify('Preparando processamento…');await engine.play();render();}};$('#applyDsp').onclick=()=>apply(+$('#dspSlider').value).catch(fail);$('#resetDsp').onclick=()=>apply(speed?100:0).catch(fail);
}
function metronome(){const q=p||freeMetro;if(q.clickFollow===false&&!rhythm.metroArmed)q.click=false;show(head('Metrônomo')+`<div class="stack"><label class="check"><input id="metroLink" type="checkbox" ${rhythmLink.linked?'checked':''}>Sincronizar com percussão</label><label class="check"><input id="clickFollow" type="checkbox" ${q.clickFollow!==false?'checked':''} ${!p?'disabled':''}>Acompanhar música</label><p>Desative para tocar com a música pausada ou parada.</p><div class="row"><button id="tap" class="primary">TAP</button><label class="check"><input id="smart" type="checkbox" ${q.smart?'checked':''} ${!p?'disabled':''}>Smart Click</label></div><p id="smartInfo">Original: ${q.bpm} BPM · Atual: ${(q.bpm*(p?globalRate(p):1)).toFixed(1)} BPM</p><label>BPM original<input id="bpm" type="number" min="30" max="300" step=".1" value="${q.bpm}"></label><div class="row"><label class="spacer">Compasso<select id="meter">${[2,3,4,5,6,7,8,12].map(n=>`<option ${n===q.meter?'selected':''}>${n}</option>`).join('')}</select></label><label class="spacer">Unidade<select id="denominator">${[4,8].map(n=>`<option ${n===(q.denominator||4)?'selected':''}>${n}</option>`).join('')}</select></label><label class="spacer">Divisão<select id="division">${[.5,1,2].map(n=>`<option value="${n}" ${n===q.clickDivision?'selected':''}>${n}x</option>`).join('')}</select></label></div><label>Timbre<select id="tone">${['Classic','Wood','High Tick','Soft','Digital','Low Tick','Cowbell','Woodblock'].map((n,i)=>`<option value="${i}" ${i===q.clickTone?'selected':''}>${n}</option>`).join('')}</select></label><label>Volume<input id="clickDb" type="range" min="-60" max="0" step="1" value="${q.clickDb}"></label><label class="check"><input id="accent" type="checkbox" ${q.clickAccent?'checked':''}>Acentuar primeira batida</label><p>0.5x / 1x / 2x alteram somente o click. Para alterar a música, use Velocidade.</p></div><div class="actions"><button id="clickPlay" class="primary">${q.click?'Ⅱ Pausar click':'▶ Play'}</button><button id="closeMetro">Fechar</button></div>`);
  $('#metroLink').onchange=async e=>{try{await rhythmLink.setLinked(e.target.checked,'metronome');if(modal.open&&$('#metroLink'))metronome();render();}catch(error){fail(error);}};
  const save=()=>{q.bpm=Math.max(30,Math.min(300,+$('#bpm').value||72));q.meter=+$('#meter').value;q.denominator=+$('#denominator').value;q.clickFollow=$('#clickFollow').checked;q.clickDivision=+$('#division').value;q.clickDb=+$('#clickDb').value;q.clickTone=+$('#tone').value;q.clickAccent=$('#accent').checked;if(p)persist();else localStorage.setItem('free-metronome',JSON.stringify({...q,click:false}));if(rhythmLink.linked)rhythmLink.sync('metronome');};listen('#bpm,#meter,#denominator,#division,#clickDb,#tone,#accent,#clickFollow','change',async()=>{save();if(rhythmLink.linked){await rhythmLink.run('metronome');if(modal.open&&$('#metroLink'))metronome();render();return;}rhythm.metroArmed=q.click;if(p)await engine.rebuild();await rhythm.click(q);});$('#tap').onclick=()=>{const now=performance.now();if(taps.length&&now-taps.at(-1)>2500)taps=[];taps.push(now);if(taps.length>6)taps.shift();if(taps.length>1){$('#bpm').value=Math.round(60000*(taps.length-1)/(taps.at(-1)-taps[0]));save();(rhythmLink.linked?rhythmLink.run('metronome'):engine.rebuild()).catch(fail);}};
  $('#smart').onchange=async()=>{q.smart=$('#smart').checked;persist();if(!q.smart)return;const t=q.tracks.find(t=>/click|clk|metro/i.test(t.name))||q.tracks.find(t=>/drum|bateria|perc/i.test(t.name))||q.tracks[0],stored=engine.buffers.get(t?.id);let b;try{b=stored?.stream?await previewBuffer(stored,await engine.context()):stored;}catch(e){fail(e);return;}if(!b)return;$('#smartInfo').textContent='Analisando pulsação…';const worker=new Worker(new URL('./analysis-worker.js',import.meta.url),{type:'module'}),samples=b.getChannelData(0).slice(0,b.sampleRate*120),project=p;worker.onmessage=({data})=>{worker.terminate();if(p!==project||!q.smart)return;if(data.bpm){q.bpm=data.bpm;if(rhythmLink.linked){rhythmLink.sync('metronome');rhythmLink.run('metronome').catch(fail);}persist();if($('#bpm')){$('#bpm').value=q.bpm;$('#smartInfo').textContent=`Original: ${q.bpm} BPM · Atual: ${(q.bpm*(p?globalRate(p):1)).toFixed(1)} BPM. Confira metade/dobro.`;}engine.rebuild().catch(fail);}else if($('#smartInfo'))$('#smartInfo').textContent='Pulsação não identificada com confiança. Use TAP.';};worker.postMessage({type:'tempo',samples,rate:b.sampleRate},[samples.buffer]);};
  $('#clickPlay').onclick=async()=>{save();q.click=!q.click;if(rhythmLink.linked){$('#clickPlay').disabled=true;try{await rhythmLink.run('metronome',true);if(modal.open&&$('#metroLink'))metronome();render();}catch(e){fail(e);metronome();}return;}rhythm.metroArmed=q.click;if(p)persist();if(q.clickFollow!==false&&p){rhythm.stopClick();if(engine.playing)await engine.rebuild();else if(q.click)await engine.play();}else{if(p&&engine.playing)await engine.rebuild();await rhythm.click(q);}$('#clickPlay').textContent=q.click?'Pausar click':'Play';};$('#closeMetro').onclick=()=>{save();modal.close();render();};
}
function sections(){const originalDuration=Math.max(0,...p.tracks.map(t=>t.duration)),pos=engine.current()*globalRate(p);show(head('Seções')+`<p>Posição musical: <b id="sectionTime">${time(pos)}</b></p><canvas id="sectionWave" class="wave"></canvas><input id="sectionSeek" aria-label="Navegar na música" type="range" min="0" max="${originalDuration}" step=".01" value="${pos}" style="width:100%"><div class="stack"><label>Nome<input id="markerName" placeholder="Refrão"></label><div class="row"><label class="spacer">Início (segundos)<input id="markerStart" type="number" min="0" step=".01" value="${pos.toFixed(2)}"></label><label class="spacer">Fim (segundos)<input id="markerEnd" type="number" min="0" step=".01" value="${Math.min(originalDuration,pos+10).toFixed(2)}"></label></div><div class="row"><button id="markStart">Usar posição no início</button><button id="markEnd">Usar posição no fim</button></div><div class="row section-colors">${['#89acf2','#88b9a0','#b29cda','#dc938a','#d0ad74','#81bdc8'].map((c,i)=>`<button style="background:${c}" data-color="${c}" aria-label="Cor ${['azul','verde','violeta','coral','âmbar','ciano'][i]}"></button>`).join('')}<label class="color-wheel" title="Escolher cor personalizada"><input id="markerColor" type="color" value="#89acf2" aria-label="Escolher cor personalizada"></label></div><button id="addMarker" class="primary">Salvar seção</button>${p.markers.map(m=>`<div class="row"><span class="spacer">${esc(m.name)} · ${time(m.start)}–${time(m.end)}</span><button data-select-marker="${m.id}">Selecionar loop</button><button data-remove-marker="${m.id}" aria-label="Excluir seção ${esc(m.name)}">×</button></div>`).join('')}</div>`);const c=$('#sectionWave');c.width=540;c.height=90;const ctx=c.getContext('2d');drawEnvelope(ctx,projectEnvelope(p.tracks),540,90);listen('[data-color]','click',(_,el)=>{$('#markerColor').value=el.dataset.color;document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('chosen',b===el));});$('#sectionSeek').oninput=e=>{$('#sectionTime').textContent=time(+e.target.value);};$('#sectionSeek').onchange=e=>engine.seek(+e.target.value/globalRate(p)).catch(fail);$('#markStart').onclick=()=>$('#markerStart').value=(engine.current()*globalRate(p)).toFixed(2);$('#markEnd').onclick=()=>$('#markerEnd').value=(engine.current()*globalRate(p)).toFixed(2);$('#addMarker').onclick=()=>{const start=+$('#markerStart').value,end=+$('#markerEnd').value;if(!(end>start&&start>=0&&end<=originalDuration+.01)){notify('O fim deve vir após o início e ficar dentro da música.');return;}p.markers.push({id:id(),name:$('#markerName').value.trim()||'Seção',start,end,color:$('#markerColor').value});persist();sections();render();};listen('[data-select-marker]','click',async(_,el)=>{p.selectedMarker=el.dataset.selectMarker;persist();await engine.rebuild();modal.close();render();});listen('[data-remove-marker]','click',async(_,el)=>{p.markers=p.markers.filter(m=>m.id!==el.dataset.removeMarker);if(p.selectedMarker===el.dataset.removeMarker)p.selectedMarker=null;persist();await engine.rebuild();sections();render();});}
function groups(type='dcas'){show(head(type==='dcas'?'DCA':'BUS')+`<div class="row"><button id="newGroup">＋ ${type==='dcas'?'DCA':'BUS'}</button></div><div class="stack">${[type].map(type=>p[type].map(g=>`<section class="panel group"><div class="row"><h3 class="spacer">${type==='dcas'?'DCA':'BUS'} · ${esc(g.name)}</h3><button data-remove-group="${type}:${g.id}">Excluir</button></div><button data-group-lock="${type}:${g.id}" aria-label="Cadeado ${esc(g.name)}">${gainLocked(g)?lockIcon(true):lockIcon(false)}</button><label>Volume · <span id="group-value-${g.id}">${g.db} dB</span><input style="width:100%" type="range" min="-80" max="10" step=".1" value="${g.db}" data-group-gain="${type}:${g.id}" ${gainLocked(g)?'disabled':''}></label><label class="check"><input type="checkbox" data-group-mute="${type}:${g.id}" ${g.mute?'checked':''}>Mute</label>${type==='dcas'?p.tracks.map(t=>`<label class="check"><input data-member="${g.id}:${t.id}" type="checkbox" ${g.members.includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join(''):'<p>Envie tracks para este BUS no Routing.</p>'}</section>`).join('')).join('')}</div>`);const create=type=>{const name=prompt(type==='dcas'?'Nome do DCA':'Nome do BUS');if(!name?.trim())return;p[type].push({id:id(),name:name.trim(),db:0,mute:false,members:[],route:'master'});persist();render();groups(type);engine.rebuild().catch(fail);};$('#newGroup').onclick=()=>create(type);listen('[data-group-lock]','click',(_,el)=>{const [kind,id]=el.dataset.groupLock.split(':');const g=p[kind].find(x=>x.id===id);const was=gainLocked(g);g.locked=!was;p.unlockedFaders=(p.unlockedFaders||[]).filter(id=>id!==g.id);if(was&&p.masterFaderLock)p.unlockedFaders.push(g.id);persist();groups(type);});listen('[data-group-gain]','input',(_,el)=>{const [type,tid]=el.dataset.groupGain.split(':'),g=p[type].find(x=>x.id===tid);if(gainLocked(g))return;g.db=+el.value;$(`#group-value-${tid}`).textContent=g.db.toFixed(1)+' dB';engine.updateMix();persist();});listen('[data-group-mute]','change',(_,el)=>{const [type,tid]=el.dataset.groupMute.split(':');p[type].find(x=>x.id===tid).mute=el.checked;engine.updateMix();persist();});listen('[data-member]','change',(_,el)=>{const [d,t]=el.dataset.member.split(':'),group=p.dcas.find(x=>x.id===d);group.members=el.checked?[...new Set([...group.members,t])]:group.members.filter(x=>x!==t);engine.updateMix();persist();});listen('[data-remove-group]','click',async(_,el)=>{const [type,tid]=el.dataset.removeGroup.split(':');p[type]=p[type].filter(x=>x.id!==tid);for(const t of p.tracks)if(t.route===tid)t.route='master';persist();await engine.rebuild();render();groups(type);});}
function routing(){const opts=route=>[['master','MASTER · estéreo'],['left','OUT 1/2 · esquerda'],['right','OUT 2/2 · direita']].map(([v,n])=>`<option value="${v}" ${v===route?'selected':''}>${n}</option>`).join('');show(head('Routing')+`<p>A versão web usa a saída estéreo disponibilizada pelo navegador. Interfaces com saídas adicionais ainda não são suportadas.</p><div class="stack">${p.tracks.map(t=>`<label>${esc(t.name)}<select data-route="${t.id}">${opts(t.route)}${p.buses.map(b=>`<option value="${b.id}" ${b.id===t.route?'selected':''}>BUS · ${esc(b.name)}</option>`).join('')}</select></label>`).join('')}${p.buses.map(b=>`<label>BUS · ${esc(b.name)}<select data-bus-route="${b.id}">${opts(b.route)}</select></label>`).join('')}<div class="routing-actions tools"><label class="routing-click">♩<span>CLICK INTERNO</span><select id="clickRoute" aria-label="Saída do click interno">${opts(p.clickRoute)}</select></label>${tool('split','STEREO SPLIT','L / R',p.tracks.length>0&&p.clickRoute==='left'&&p.tracks.every(t=>t.route===(/click|guide|guia|clk/i.test(t.name)?'left':'right')))}${tool('bothAll','BOTH ALL','Estéreo',p.clickRoute==='master'&&p.tracks.every(t=>t.route==='master'))}</div></div>`);listen('[data-route]','change',async(_,el)=>{p.tracks.find(t=>t.id===el.dataset.route).route=el.value;persist();await engine.rebuild();routing();});listen('[data-bus-route]','change',async(_,el)=>{p.buses.find(b=>b.id===el.dataset.busRoute).route=el.value;persist();await engine.rebuild();routing();});$('#clickRoute').onchange=async e=>{p.clickRoute=e.target.value;persist();await engine.rebuild();routing();};$('#split').onclick=async()=>{for(const t of p.tracks)t.route=/click|guide|guia|clk/i.test(t.name)?'left':'right';p.clickRoute='left';persist();await engine.rebuild();routing();};$('#bothAll').onclick=async()=>{for(const t of p.tracks)t.route='master';p.clickRoute='master';persist();await engine.rebuild();routing();};}

function renderTuner(){const pref=tunerPrefs,inst=instruments[pref.instrument]||instruments[1],tunings=inst[1],notes=tunings[pref.tuning]?.[1]||[];app.innerHTML=`<section class="tuner"><div class="row between"><h1>Afinador</h1><button id="back">Voltar aos projetos</button></div><p>Análise local pelo microfone. O player permanece pausado.</p><div class="panel tuner-grid"><div class="stack tuner-controls"><label>Instrumento<select id="instrument">${instruments.map(([name],i)=>`<option value="${i}" ${i===pref.instrument?'selected':''}>${name}</option>`).join('')}</select></label>${notes.length?`<label>Afinação<select id="tuning">${tunings.map(([name],i)=>`<option value="${i}" ${i===pref.tuning?'selected':''}>${name}</option>`).join('')}</select></label><label>Corda<select id="string"><option value="-1">AUTO</option>${notes.map((n,i)=>`<option value="${i}" ${i===pref.string?'selected':''}>${notes.length-i}ª · ${noteName(n)}</option>`).join('')}</select></label>`:''}<label>Referência A4 (Hz)<input id="a4" type="number" min="400" max="480" value="${pref.a4}"></label><button id="resetA4">Reset 440 Hz</button><label>MIC<progress id="mic" value="0" max="1"></progress></label><button id="micStart" class="primary">Permitir microfone</button></div><div class="tuner-reading" id="reading"><div class="note" id="note">—</div><p class="frequency" id="freq">AGUARDANDO SINAL</p><p id="target">Toque uma corda</p><div class="gauge"><span class="needle" id="needle"></span></div><div class="gauge-labels"><span>−50</span><span>−25</span><span>0</span><span>+25</span><span>+50</span></div><div class="cents" id="cents">— cents</div><p class="direction" id="direction">O microfone é usado somente nesta tela.</p></div></div></section>`;
  $('#back').onclick=()=>navigate('projects');const save=()=>localStorage.setItem('tuner',JSON.stringify(pref));$('#instrument').onchange=e=>{pref.instrument=+e.target.value;pref.tuning=0;pref.string=-1;save();tuner.stop();renderTuner();};if($('#tuning'))$('#tuning').onchange=e=>{pref.tuning=+e.target.value;pref.string=-1;save();tuner.stop();renderTuner();};if($('#string'))$('#string').onchange=e=>{pref.string=+e.target.value;save();};$('#a4').onchange=e=>{pref.a4=Math.max(400,Math.min(480,+e.target.value||440));e.target.value=pref.a4;save();};$('#resetA4').onclick=()=>{pref.a4=440;$('#a4').value=440;save();};
  $('#micStart').onclick=async()=>{try{$('#micStart').disabled=true;await tuner.start(r=>{if(screen!=='tuner'||!$('#note'))return;$('#mic').value=Math.min(1,r.rms*8);if(r.error){$('#direction').textContent='Falha na análise. Ative o microfone novamente.';$('#micStart').disabled=false;return;}if(!r.frequency){$('#note').textContent='—';$('#freq').textContent='AGUARDANDO SINAL ESTÁVEL';$('#cents').textContent='— cents';$('#target').textContent='Toque uma corda';$('#direction').textContent='AGUARDANDO SINAL ESTÁVEL';$('#needle').style.left='50%';$('#reading').classList.remove('tuned');return;}const d=tunerReading(r.frequency,notes,pref.string,pref.a4),delta=d.targetCents??d.cents,tuned=Math.abs(delta)<=3;$('#note').textContent=noteName(d.midi);$('#freq').textContent=r.frequency.toFixed(2)+' Hz';$('#cents').textContent=`${d.cents>=0?'+':''}${d.cents.toFixed(1)} cents · nota captada`;$('#target').textContent=d.target===null?'Modo cromático':`Alvo: ${notes.length-notes.indexOf(d.target)}ª corda · ${noteName(d.target)} · ${delta>=0?'+':''}${delta.toFixed(1)} cents` ;$('#needle').style.left=(50+Math.max(-50,Math.min(50,d.cents)))+'%';$('#reading').classList.toggle('tuned',tuned);$('#direction').textContent=tuned?'AFINADO':delta<0?'↑ AUMENTE A AFINAÇÃO':'↓ DIMINUA A AFINAÇÃO';});if($('#micStart')){$('#micStart').textContent='Microfone ativo';$('#micStart').disabled=false;}}catch(e){console.error(e);if($('#micStart')){$('#micStart').disabled=false;$('#direction').textContent='Permita o microfone nas configurações do site e tente novamente. É necessário HTTPS.';}}};
}
document.addEventListener('visibilitychange',()=>{if(document.hidden){pad.stop();tuner.stop();if(screen==='tuner'&&$('#micStart'))$('#micStart').textContent='Retomar microfone';}});
const pix='atelestechnology@jim.com';
function renderSupport(){app.innerHTML=`<div class="row between"><h1>Deixe sua marca</h1><button id="back">Voltar aos projetos</button></div><div class="panel" style="max-width:850px;margin:auto"><h2>SeuNomeNoApp</h2><input id="findName" placeholder="Pesquisar nome no globo" aria-label="Pesquisar nome no globo"><button id="globeAuto">ROTAÇÃO AUTOMÁTICA</button><canvas class="globe" id="globe"></canvas><p class="muted" id="globeLabel"></p><p>Chave Pix: <strong>${pix}</strong></p><button id="copyPix">Copiar chave Pix</button><p>Contribua com um valor acima de U$ 5,00 (Cinco dólares) e deixe sua marca no Globo ATMyTrack</p><div class="actions"><button id="shareName">Enviar comprovante no WhatsApp</button></div><p class="footer">Beneficiário informado: 64.876.586 ANDRE SOUZA TELES. Confira os dados no aplicativo do seu banco antes de confirmar.</p><p class="footer">Envie o comprovante pelo WhatsApp +55 11 97031-7078.</p></div>`;$('#back').onclick=()=>navigate('projects');$('#copyPix').onclick=()=>navigator.clipboard.writeText(pix).then(()=>notify('Pix copiado.')).catch(fail);$('#shareName').onclick=()=>{const text='Olá! Fiz um Pix para ATMyTrack. Vou enviar o comprovante nesta conversa.';window.open('https://wa.me/5511970317078?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');};drawGlobe();}
async function drawGlobe(){const people=await fetch('assets/supporters.json').then(r=>r.json());if(!$('#globe'))return;const c=$('#globe'),ctx=c.getContext('2d');let yaw=0,pitch=0,drag=null,paused=false,focus='',down=null,visible=[];const points=people.map((p,i)=>{const y=1-2*(i+.5)/people.length,r=Math.sqrt(1-y*y),phi=i*Math.PI*(3-Math.sqrt(5));return {...p,x:Math.cos(phi)*r,y,z:Math.sin(phi)*r};});const initial=points.find(p=>p.name==='André Teles');if(initial){yaw=-Math.atan2(initial.x,initial.z);pitch=Math.atan2(initial.y,Math.hypot(initial.x,initial.z));focus=initial.name;$('#globeLabel').textContent=initial.name;}$('#globeAuto').onclick=()=>{paused=false;focus='';$('#findName').value='';$('#globeLabel').textContent='Arraste ou toque em um nome.';};c.onpointerdown=e=>{down=[e.clientX,e.clientY];drag=[e.clientX,e.clientY];paused=true;c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.008;pitch+=(e.clientY-drag[1])*.008;drag=[e.clientX,e.clientY];};const release=e=>{if(e&&down&&Math.hypot(e.clientX-down[0],e.clientY-down[1])<8){const r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,person=visible.find(p=>Math.abs(x-p.px)<Math.max(24,p.name.length*4)&&Math.abs(y-p.py)<14);if(person){focus=person.name;$('#findName').value=person.name;$('#globeLabel').textContent=person.name;const original=points.find(p=>p.name===person.name);yaw=-Math.atan2(original.x,original.z);pitch=Math.atan2(original.y,Math.hypot(original.x,original.z));}}down=null;drag=null;paused=!!$('#findName').value.trim();};c.onpointerup=release;c.onpointercancel=release;c.onlostpointercapture=release;$('#findName').oninput=e=>{const person=points.find(p=>p.name.toLowerCase().includes(e.target.value.toLowerCase()));paused=!!e.target.value;focus=person?.name||'';if(paused&&person){yaw=-Math.atan2(person.x,person.z);pitch=Math.atan2(person.y,Math.sqrt(person.x**2+person.z**2));$('#globeLabel').textContent=person.name;}};const tick=()=>{if(screen!=='support'||!c.isConnected)return;const width=c.clientWidth;c.width=width*devicePixelRatio;c.height=340*devicePixelRatio;ctx.scale(devicePixelRatio,devicePixelRatio);ctx.clearRect(0,0,width,340);if(!paused&&!drag)yaw+=.002;const radius=Math.min(width*.37,135);ctx.strokeStyle='#424b55';ctx.lineWidth=1;ctx.beginPath();ctx.arc(width/2,170,radius,0,Math.PI*2);ctx.stroke();visible=points.map(p=>{const x=p.x*Math.cos(yaw)+p.z*Math.sin(yaw),z=p.z*Math.cos(yaw)-p.x*Math.sin(yaw),y=p.y*Math.cos(pitch)-z*Math.sin(pitch),depth=z*Math.cos(pitch)+p.y*Math.sin(pitch);return {...p,px:width/2+x*radius,py:170+y*radius,depth};}).sort((a,b)=>a.depth-b.depth);visible.forEach(p=>{ctx.globalAlpha=.3+.7*(p.depth+1)/2;ctx.fillStyle=p.name===focus?'#80d9ec':'#b8c1cc';ctx.font=`${12+(p.depth+1)*2}px Segoe UI`;ctx.textAlign='center';ctx.fillText(p.name,p.px,p.py);});ctx.globalAlpha=1;requestAnimationFrame(tick);};tick();}
function renderHelp(){app.innerHTML=`<div class="row between"><h1>Central de dúvidas</h1><button id="back">Voltar aos projetos</button></div><section class="panel stack" style="max-width:900px"><h2>Preparar e tocar</h2><p>Importe as tracks de uma música em um projeto. Os formatos disponíveis dependem do navegador (WAV e MP3 são boas opções). Play usa um único relógio para todas as tracks. Navegar pelo menu não reinicia a música.</p><h3>Mixer, DCA e BUS</h3><p>Faders começam em 0 dB. O botão 0dB retorna ao volume original. Pan, Mute e Solo são independentes. Arraste o nome de uma track para reorganizar o canal. DCA controla ganhos de um grupo; BUS soma tracks e permite encaminhar o grupo. Routing e Stereo split oferecem esquerda, direita e estéreo da saída do navegador.</p><h3>Tom e velocidade</h3><p>Tom altera semitons; Velocidade altera duração preservando o pitch. Seleções independentes e reset. Em 100% com tom original, o DSP é ignorado. Todas as tracks na mesma velocidade acompanham o BPM e o click. Seleções diferentes podem perder sincronização. Mudanças durante Play fazem uma pequena preparação e retomam a posição musical.</p><h3>Seções e loop</h3><p>Crie início/fim na timeline original. Toque na seção para navegar, segure para selecioná-la e ative Loop. Sem seção selecionada, Loop repete o projeto. As posições são convertidas conforme a velocidade.</p><h3>CrossMusic e Percussão</h3><p>CrossMusic salva uma sequência com volume/mute por faixa e PAD por projeto. A próxima música começa ao fim natural; pausar ou fazer seek não avança a sequência. Encerrar a automação mantém a música e o PAD atuais. Percussão usa gravações reais de bateria acústica e percussão, com variações em frases de quatro compassos. Tem 10 batidas, BPM, compasso, volume e loops importados de até 60 s, com ajuste de duração sem mudar a afinação. Informe quantos compassos o loop contém. No modo independente, click e percussão continuam com a música pausada/parada. Sincronizar com metrônomo/percussão é uma única opção, ativada por padrão: os dois compartilham BPM, compasso e Acompanhar música; Play/Pausar em qualquer painel controla ambos.</p><h3>Metrônomo</h3><p>Acompanhar música conserva o modo anterior; desative para usar o click independente, inclusive sem projeto. TAP define o BPM por toques. Smart Click estima a pulsação de Click/Drums: confira metade/dobro. A divisão 0.5x/1x/2x afeta somente o click. Com Acompanhar música ativo, Play no painel ativa o click e inicia a música. No modo independente, inicia somente o click.</p><p>Gravações CC0: Virtuosity Drums (Versilian Studios/Karoryfer, Austin McMahon) e VCSL. <a href="assets/drumkit/CREDITS.md">Créditos da biblioteca acústica</a>.</p><h3>Afinador</h3><p>Permita o microfone quando solicitado. A nota grande é sempre a nota captada, com sustenido quando aplicável. A corda-alvo aparece separadamente. AUTO sugere a corda mais próxima; se estiver muito desafinada, selecione manualmente. Azul indica ±3 cents do alvo. A4 padrão 440 Hz. O microfone é encerrado ao sair ou ocultar a página.</p><h3>Seus arquivos</h3><p>Áudio e projetos ficam apenas neste navegador, sem conta ou envio ao servidor. Exporte um backup regularmente; limpar dados do site pode apagar a biblioteca. O backup web pode ser importado em outro navegador. Projetos Android não são importados automaticamente.</p><h3>Limites da versão web</h3><p>Mantenha a página aberta e a tela ativa. Suspensão em segundo plano e limites de memória variam por navegador. A reprodução lê blocos do armazenamento local, sem limite fixo de 384 MB por projeto. O tamanho disponível depende do espaço liberado pelo navegador. WAV PCM é lido diretamente; outros formatos são preparados por arquivo e dependem do decoder disponível. Interfaces USB com mais de dois canais e paridade de performance com o Android não são garantidas. Teste seu aparelho antes de usar ao vivo.</p><p><a href="vendor/Signalsmith-LICENSE.txt">Signalsmith Stretch · licença MIT</a></p></section>`;$('#back').onclick=()=>navigate('projects');}
setInterval(()=>{if(screen==='projects'&&p){if($('#clock'))$('#clock').textContent=time(engine.current())+' / '+time(duration(p));if($('#play')){$('#play').textContent=engine.busy?'Preparando…':engine.playing?'Ⅱ Pausar':'▶ Play';$('#play').disabled=loading||engine.busy||!engine.ready;}drawWave();for(const [tid,peak]of engine.meters()){const el=document.getElementById('meter-'+tid);if(el){el.style.height=Math.max(0,Math.min(100,(20*Math.log10(Math.max(1e-6,peak))+60)/60*100))+'%';el.style.background=peak>=1?'#d86d69':peak>.8?'#d0ad74':'#88b9a0';}}}},80);
try{projects=(await DB.allProjects()).map(migrate).sort((a,b)=>(a.order??1e9)-(b.order??1e9));if(projects.length)await choose(projects[0]);else render();}catch(e){render();fail(e);}

function validColor(value){return /^#[0-9a-f]{6}$/i.test(value)?value:'#89acf2';}
function waveform(buffer){return new Promise((resolve,reject)=>{const worker=new Worker('./waveform-worker.js',{type:'module'}),channels=Array.from({length:buffer.numberOfChannels},(_,i)=>buffer.getChannelData(i).slice());worker.onmessage=e=>{worker.terminate();resolve(e.data);};worker.onerror=e=>{worker.terminate();reject(new Error('Não foi possível desenhar a waveform.'));};worker.postMessage(channels,channels.map(c=>c.buffer));});}
function tool(id,label,value,active=false){const paths={pitch:'M8 3L6 21M18 3L16 21M3 9L21 7M3 17L21 15',speed:'M4 18A9 9 0 1 1 20 18M12 12L18 6',loop:'M20 7A9 9 0 1 0 21 16M20 2V7H15',sections:'M5 22V3H20V13H5',metronome:'M12 2L3 21H21ZM12 17L19 5',groups:'M5 3V21M12 3V21M19 3V21M2 8H8M9 15H15M16 10H22',routing:'M2 12H10L20 3M10 12L20 21',pad:'M3 9V15M7 5V19M12 2V22M17 5V19M21 9V15',percussion:'M3 9Q12 4 21 9V20H3ZM3 9Q12 14 21 9M6 2L16 9M18 2L9 9',crossmusic:'M3 3L12 12L3 21ZM13 3L22 12L13 21',refresh:'M20 7A9 9 0 1 0 21 16M20 2V7H15'};return `<button id="${id}" title="${label}" aria-label="${label}" class="dsp ${active?'active':''}"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[id]||(id==='split'?paths.routing:id==='bothAll'?'M4 5V19M20 5V19M4 12H20':paths.groups)}"/></svg><span>${({speed:'VELOC.',metronome:'CLICK',crossmusic:'CROSS',percussion:'PERC.',refresh:'SAÍDA',sections:'SEÇÃO'})[id]||label}<b>${value}</b></span></button>`;}

function padDialog(){const notes=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'],s=pad.settings;show(head('PAD')+`<div class="stack"><p>Camada ambiente independente da música.</p><label>Tom<select id="padNote">${notes.map((n,i)=>`<option value="${i}" ${i===s.note?'selected':''}>${n}</option>`).join('')}</select></label><label>Modo<select id="padMode"><option value="major" ${!s.minor?'selected':''}>Maior</option><option value="minor" ${s.minor?'selected':''}>Menor</option></select></label><label>Som<select id="padSound">${Object.entries(Pad.sounds).map(([id,v])=>`<option value="${id}" ${id===(s.sound||"Warm")?"selected":""}>${v.label}</option>`).join("")}</select></label><label>Volume do PAD<input id="padVolume" type="range" min="0" max="1" step=".01" value="${s.volume}"></label><p>${pad.playing?'SOANDO':'PARADO'}</p><div class="actions"><button id="padPlay" class="primary">▶ Play PAD</button><button id="padStop">■ Stop PAD</button></div></div>`);$('#padNote').onchange=e=>pad.configure({note:+e.target.value});$('#padMode').onchange=e=>pad.configure({minor:e.target.value==='minor'});$('#padSound').onchange=e=>pad.configure({sound:e.target.value});$('#padVolume').oninput=e=>pad.configure({volume:+e.target.value});$('#padPlay').onclick=async()=>{try{await pad.play();render();padDialog();}catch(e){console.error(e);notify("Não foi possível reproduzir o PAD. Confira a saída de áudio.");}};$('#padStop').onclick=()=>{pad.stop();render();padDialog();};}

function renderTools(){
 const host=$('#toolHost');if(!host)return;if(screen!=='projects'){host.innerHTML='';return;}
 const items=[...(p?[['pitch','TOM',()=>dsp('pitch'),!!p.pitch],['speed','VELOCIDADE',()=>dsp('speed'),p.speed!==100]]:[]),['pad','PAD',padDialog,pad.playing],['metronome','METRÔNOMO',metronome,p?.click||rhythm.metroArmed],['percussion','PERCUSSÃO',percussionDialog,rhythm.enabled],...(p?[['loop','LOOP',async()=>{p.loop=!p.loop;persist();await engine.rebuild();render();},p.loop],['sections','+ SEÇÃO',sections,false]]:[]),...(p?[['dcas','DCA',()=>groups('dcas')],['buses','BUS',()=>groups('buses')],['routing','ROUTING',routing],['refresh','ATUALIZAR SAÍDA',outputDialog]]:[]),['crossmusic','CROSSMUSIC',crossDialog,cross.active]];
 host.innerHTML='<button id="toolsToggle" aria-label="Ferramentas" aria-expanded="false">☷</button><div id="toolsPanel" class="tools">'+items.map(([id,label,action,active])=>tool(id,label,id==='speed'?p.speed+'%':id==='pitch'?(p.pitch>=0?'+':'')+p.pitch:'',!!active)).join('')+'</div>';
 $('#toolsToggle').onclick=()=>{host.classList.toggle('tools-open');$('#toolsToggle').setAttribute('aria-expanded',host.classList.contains('tools-open'));};
 for(const [id,label,action] of items)$('#'+id).onclick=()=>{host.classList.remove('tools-open');Promise.resolve().then(action).catch(fail);};
}
function importDialog(){if(loading)return;show(head('Importar projeto')+'<p>Importe uma pasta ou várias faixas. Os arquivos originais permanecem intactos.</p><div class="stack"><button id="importFolder">IMPORTAR PASTA</button><button id="importMultiple">IMPORTAR ARQUIVOS</button>'+(p?'<button id="importHere">Adicionar faixas ao projeto atual</button>':'')+'</div>');$('#importFolder').onclick=()=>{importTarget=null;modal.close();$('#folderFiles').click();};$('#importMultiple').onclick=()=>{modal.close();startImport(null);};if($('#importHere'))$('#importHere').onclick=()=>{modal.close();startImport(p);};}
$('#folderFiles').onchange=e=>$('#files').onchange(e);
$('#import').onclick=importDialog;
function fineGain(id){const c=channel(id),value=c.master?p.master:c.ref.db;show(head('Volume · '+esc(c.master?'Master':c.ref.name))+'<label>dB<input id="fineDb" type="number" min="-80" max="10" step=".1" value="'+value+'"></label><div class="row"><button id="dbMinus">−0,1</button><button id="dbPlus">+0,1</button><button id="dbUnity">UNITY</button><button id="dbSilence">SILÊNCIO</button></div><button id="dbApply" class="primary">APLICAR</button>');const apply=v=>{if(Number.isFinite(v)&&v>=-80&&v<=10){setDb(id,Math.round(v*10)/10);$('#fineDb').value=v;}else notify('Informe um volume de −80 a +10 dB.');};$('#dbMinus').onclick=()=>apply(+(+$('#fineDb').value-.1).toFixed(1));$('#dbPlus').onclick=()=>apply(+(+$('#fineDb').value+.1).toFixed(1));$('#dbUnity').onclick=()=>apply(0);$('#dbSilence').onclick=()=>apply(-80);$('#dbApply').onclick=()=>{apply(+$('#fineDb').value);modal.close();};}
async function saveOrder(){await Promise.all(projects.map((x,i)=>{x.order=i;return DB.saveProject(x);}));}
async function moveProject(id,delta){const i=projects.findIndex(x=>x.id===id),j=i+delta;if(j<0||j>=projects.length)return;[projects[i],projects[j]]=[projects[j],projects[i]];await saveOrder();render();}
async function moveCard(id,target){const i=projects.findIndex(x=>x.id===id),j=projects.findIndex(x=>x.id===target);if(i<0||j<0||i===j)return;projects.splice(j,0,projects.splice(i,1)[0]);await saveOrder();render();}

function bindCards(){
 listen('[data-edit-card]','click',async(_,el)=>{const x=projects.find(x=>x.id===el.dataset.editCard);if(await choose(x))editProject();});
 listen('[data-delete-card]','click',async(_,el)=>{const x=projects.find(x=>x.id===el.dataset.deleteCard);if(!confirm('Excluir '+x.name+'? Os arquivos originais serão preservados.'))return;if(x===p){engine.stop();rhythm.stopClick();}await DB.deleteProject(x);projects=projects.filter(q=>q!==x);if(x===p){p=null;engine.project=null;if(projects.length)await choose(projects[0]);}render();});
 let dragged;listen('[data-card]','dragstart',(e,el)=>{dragged=el.dataset.card;e.dataTransfer.setData('text/plain',dragged);el.classList.add('dragging');});listen('[data-card]','dragover',e=>e.preventDefault());listen('[data-card]','drop',(e,el)=>{e.preventDefault();cardDragTime=Date.now();moveCard(dragged,el.dataset.card).catch(fail);});listen('[data-card]','dragend',(_,el)=>el.classList.remove('dragging'));
 listen('.card-select','pointerdown',(event,button)=>{if(event.pointerType==='mouse')return;const card=button.closest('[data-card]'),cards=card.parentElement,start=event.clientX;let held=false,last=start,target=card.dataset.card;const timer=setTimeout(()=>{held=true;card.classList.add('dragging');},400);button.setPointerCapture(event.pointerId);button.onpointermove=e=>{if(!held){if(Math.abs(e.clientX-start)>12)clearTimeout(timer);cards.scrollLeft-=e.clientX-last;last=e.clientX;return;}e.preventDefault();const bounds=[...cards.querySelectorAll('[data-card]')].map(el=>({id:el.dataset.card,r:el.getBoundingClientRect()}));target=bounds.reduce((best,x)=>Math.abs(x.r.left+x.r.width/2-e.clientX)<best.distance?{id:x.id,distance:Math.abs(x.r.left+x.r.width/2-e.clientX)}:best,{id:target,distance:Infinity}).id;const r=cards.getBoundingClientRect();if(e.clientX<r.left+36)cards.scrollLeft-=12;if(e.clientX>r.right-36)cards.scrollLeft+=12;};const end=()=>{clearTimeout(timer);button.onpointermove=null;card.classList.remove('dragging');if(held){cardDragTime=Date.now();moveCard(card.dataset.card,target).catch(fail);}};button.onpointerup=end;button.onpointercancel=()=>{clearTimeout(timer);button.onpointermove=null;card.classList.remove('dragging');};});
 document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',e=>{if(Date.now()-cardDragTime<600){e.stopImmediatePropagation();e.preventDefault();}},true));
}
async function analyzeKey(project){
 const candidates=project.tracks.filter(t=>!/click|clk|metro|guide|guia|drum|bateria|perc/i.test(t.name)).sort((a,b)=>(/piano|guitar|viol|keys|tecla|pad/i.test(a.name)?0:1)-(/piano|guitar|viol|keys|tecla|pad/i.test(b.name)?0:1)).slice(0,3);
 for(const t of candidates){const source=engine.buffers.get(t.id);if(!source)continue;const buffer=source.stream?await previewBuffer(source,await engine.context(),30):source;const l=buffer.getChannelData(0),r=buffer.getChannelData(Math.min(1,buffer.numberOfChannels-1));let left=0,right=0;for(let i=0;i<l.length;i+=16){left+=l[i]*l[i];right+=r[i]*r[i];}const samples=(left>=right?l:r).slice();const estimate=await new Promise(resolve=>{const worker=new Worker(new URL('./key-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{worker.terminate();resolve(data);};worker.onerror=()=>{worker.terminate();resolve(null);};worker.postMessage({samples,rate:buffer.sampleRate},[samples.buffer]);});if(estimate){project.key=estimate.name;project.keyConfidence=estimate.confidence;break;}}
 project.keyAnalyzed=true;
}
async function percussionDialog(){const s=rhythm.settings;show(head('Percussão')+'<p>Bateria acústica e percussão gravadas · variação natural em quatro compassos.</p><div class="stack"><label class="check"><input id="percLink" type="checkbox" '+(rhythmLink.linked?'checked':'')+'>Sincronizar com metrônomo</label><label class="check"><input id="percFollow" type="checkbox" '+(s.follow?'checked':'')+'>Acompanhar música</label><p>'+ (s.follow?(p?'Segue a música · '+(p.bpm*globalRate(p)).toFixed(1)+' BPM · '+meterLabel(p):'Selecione um projeto para acompanhar.'):'Ritmo independente: toca com a música pausada ou parada.')+'</p><label>Batida<select id="percSource">'+patterns.map(n=>'<option value="'+esc(n)+'" '+(s.source===n?'selected':'')+'>'+esc(n)+'</option>').join('')+rhythm.library.map(x=>'<option value="'+x.id+'" '+(s.source===x.id?'selected':'')+'>Importado · '+esc(x.name)+'</option>').join('')+'</select></label><button id="percTap" '+(s.follow&&!rhythmLink.linked?'disabled':'')+'>TAP BPM</button><small id="percTapInfo">'+(s.follow&&!rhythmLink.linked?'Desative Acompanhar música para definir um BPM separado por toques.':'Toque pelo menos duas vezes no ritmo desejado.')+'</small>'+(!s.follow?'<label>BPM (30–300)<input id="percBpm" type="number" min="30" max="300" step=".1" value="'+s.bpm+'"></label><label>Compasso<select id="percMeter">'+['2/4','3/4','4/4','6/8','7/8'].map(n=>'<option '+(n===s.meter+'/'+s.denominator?'selected':'')+'>'+n+'</option>').join('')+'</select></label>':'')+(!patterns.includes(s.source)?'<label>Compassos no áudio<select id="percBars">'+[1,2,4,8,16,32,64].map(n=>'<option '+(n===s.bars?'selected':'')+'>'+n+'</option>').join('')+'</select></label><p>Informe quantos compassos o loop contém. O ajuste de BPM preserva a afinação.</p>':'')+'<label>Volume<input id="percVolume" type="range" min="0" max="1" step=".01" value="'+s.volume+'"></label><button id="percImport">IMPORTAR ÁUDIO</button><p class="footer">Loops de 0,05 a 60 segundos. Guardados neste navegador, sem alterar seus projetos. Ajuste final até 120 s, de 0,125× a 8×.</p><p id="percState">'+(rhythm.preparing?'Preparando batida…':rhythm.enabled?(s.follow?'ATIVADA · acompanha o transporte':'TOCANDO · independente'):'PARADA')+'</p></div><div class="actions"><button id="percPlay" class="primary">'+(rhythm.enabled?'■ PARAR':'▶ PLAY')+'</button></div>');
 $('#percTap').onclick=async()=>{const value=percussionTap.tap(performance.now());if(value===null){$('#percTapInfo').textContent='Toque novamente para definir o BPM.';return;}s.bpm=value;if(rhythmLink.linked)await rhythmLink.run('percussion');else await rhythm.refresh();render();if(modal.open&&$('#percLink'))percussionDialog();if($('#percTapInfo'))$('#percTapInfo').textContent='BPM pelos toques: '+value.toFixed(1);};
 $('#percLink').onchange=async e=>{try{await rhythmLink.setLinked(e.target.checked,'percussion');if(modal.open&&$('#percLink'))percussionDialog();render();}catch(error){fail(error);}};
 const refresh=async(startMusic=false)=>{s.follow=$('#percFollow').checked;s.source=$('#percSource').value;if($('#percBpm')){const bpm=+$('#percBpm').value;if(!Number.isFinite(bpm)||bpm<30||bpm>300)throw Error('Informe BPM de 30 a 300.');s.bpm=bpm;[s.meter,s.denominator]=$('#percMeter').value.split('/').map(Number);}if($('#percBars'))s.bars=+$('#percBars').value;if(rhythmLink.linked)await rhythmLink.run('percussion',startMusic);else await rhythm.refresh();};
 listen('#percFollow,#percSource,#percBpm,#percMeter,#percBars','change',async()=>{await refresh();render();if(modal.open&&$('#percLink'))percussionDialog();});$('#percVolume').oninput=e=>rhythm.volume(+e.target.value);$('#percPlay').onclick=async()=>{rhythm.enabled=!rhythm.enabled;$('#percPlay').disabled=true;try{await refresh(true);render();if(modal.open&&$('#percLink'))percussionDialog();}catch(e){fail(e);if($('#percState'))$('#percState').textContent=e.message;if($('#percPlay'))$('#percPlay').disabled=false;}};$('#percImport').onclick=()=>$('#percussionFile').click();
}
$('#percussionFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{notify('Importando loop…');await rhythm.import(file);if(rhythmLink.linked)await rhythmLink.run('percussion');percussionDialog();}catch(e){fail(e);}};
function entryFor(project){return {projectId:project.id,tracks:Object.fromEntries(project.tracks.map(t=>[t.id,{db:t.db,mute:t.mute}])),pad:{enabled:false,follow:true,note:0,minor:false,volume:.25,sound:'Warm'}};}
function saveCross(){localStorage.setItem('crossmusic',JSON.stringify(crossPlan));}

function crossDialog(){show(head('CrossMusic')+'<p>'+(cross.active?'Em execução · '+(cross.index+1)+'/'+cross.total:'Marque os projetos na ordem de reprodução. Ajuste faixas e PAD por música.')+'</p><div class="stack">'+projects.map(project=>{const i=crossPlan.findIndex(e=>e.projectId===project.id),entry=crossPlan[i]||entryFor(project),disabled=cross.active?'disabled':'';return '<section class="panel cross-entry"><div class="row"><label class="check spacer"><input data-cross-include="'+project.id+'" type="checkbox" '+(i>=0?'checked':'')+' '+disabled+'>'+esc(project.name)+(i>=0?' · '+(i+1)+'º':'')+'</label><button data-cross-up="'+project.id+'" '+(i<1||cross.active?'disabled':'')+'>↑</button><button data-cross-down="'+project.id+'" '+(i<0||i>=crossPlan.length-1||cross.active?'disabled':'')+'>↓</button></div><details data-cross-details="'+project.id+'" '+(crossExpanded.has(project.id)?'open':'')+'><summary>Faixas e PAD</summary><fieldset '+(i<0||cross.active?'disabled':'')+'>'+project.tracks.map(t=>{const m=entry.tracks[t.id]||{db:t.db,mute:t.mute};return '<label>'+esc(t.name)+' · <span data-cross-value="'+project.id+':'+t.id+'">'+dbText(m.db)+' dB</span><input data-cross-volume="'+project.id+':'+t.id+'" type="range" min="-80" max="10" step=".1" value="'+m.db+'"></label><label class="check"><input data-cross-mute="'+project.id+':'+t.id+'" type="checkbox" '+(m.mute?'checked':'')+'>Mute</label>';}).join('')+'<label class="check"><input data-cross-pad="'+project.id+':enabled" type="checkbox" '+(entry.pad.enabled?'checked':'')+'>Ativar PAD</label><label class="check"><input data-cross-pad="'+project.id+':follow" type="checkbox" '+(entry.pad.follow?'checked':'')+'>Tom do projeto ('+esc(targetKey(project)||'não definido')+')</label><label>Tom manual<select data-cross-pad="'+project.id+':note">'+NOTES.map((n,j)=>'<option value="'+j+'" '+(entry.pad.note===j?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="check"><input data-cross-pad="'+project.id+':minor" type="checkbox" '+(entry.pad.minor?'checked':'')+'>Menor</label><label>Timbre<select data-cross-pad="'+project.id+':sound">'+Object.entries(Pad.sounds).map(([id,x])=>'<option value="'+id+'" '+(entry.pad.sound===id?'selected':'')+'>'+x.label+'</option>').join('')+'</select></label><label>Volume PAD<input data-cross-pad="'+project.id+':volume" type="range" min="0" max="1" step=".01" value="'+entry.pad.volume+'"></label></fieldset></details></section>';}).join('')+'</div><div class="actions"><button id="crossStart" class="primary" '+(cross.active||!crossPlan.length?'disabled':'')+'>INICIAR CROSSMUSIC</button><button id="crossEnd" '+(!cross.active?'disabled':'')+'>ENCERRAR</button></div>');
 listen('[data-cross-details]','toggle',(_,el)=>{if(el.open)crossExpanded.add(el.dataset.crossDetails);else crossExpanded.delete(el.dataset.crossDetails);});
 listen('[data-cross-include]','change',(_,el)=>{const project=projects.find(p=>p.id===el.dataset.crossInclude);crossPlan=el.checked?[...crossPlan,entryFor(project)]:crossPlan.filter(e=>e.projectId!==project.id);saveCross();crossDialog();});
 listen('[data-cross-up],[data-cross-down]','click',(_,el)=>{const id=el.dataset.crossUp||el.dataset.crossDown,i=crossPlan.findIndex(e=>e.projectId===id),j=i+(el.dataset.crossUp?-1:1);if(j>=0&&j<crossPlan.length)[crossPlan[i],crossPlan[j]]=[crossPlan[j],crossPlan[i]];saveCross();crossDialog();});
 listen('[data-cross-volume],[data-cross-mute]','input',(_,el)=>{const [id,tid]=(el.dataset.crossVolume||el.dataset.crossMute).split(':'),entry=crossPlan.find(e=>e.projectId===id);if(!entry)return;entry.tracks[tid]??={db:0,mute:false};if(el.dataset.crossVolume){entry.tracks[tid].db=+el.value;document.querySelector('[data-cross-value="'+id+':'+tid+'"]').textContent=dbText(+el.value)+' dB';}else entry.tracks[tid].mute=el.checked;saveCross();});
 listen('[data-cross-pad]','change',(_,el)=>{const [id,key]=el.dataset.crossPad.split(':'),entry=crossPlan.find(e=>e.projectId===id);if(!entry)return;entry.pad[key]=el.type==='checkbox'?el.checked:['note','volume'].includes(key)?+el.value:el.value;saveCross();});$('#crossStart').onclick=()=>startCross().catch(fail);$('#crossEnd').onclick=endCross;
}
async function startCross(){const entries=crossPlan.filter(e=>projects.some(p=>p.id===e.projectId));if(!entries.length)throw Error('Selecione projetos para o CrossMusic.');for(const entry of entries){const project=projects.find(p=>p.id===entry.projectId);if(entry.pad.enabled&&entry.pad.follow&&!keyParts(targetKey(project)))throw Error('Defina o tom de '+project.name+' ou escolha o tom manual do PAD.');}engine.pause();cross={active:true,index:0,total:entries.length,preparing:true,entries:structuredClone(entries),generation:++crossGeneration};modal.close();await advanceCross(0);}
async function advanceCross(index){if(!cross.active)return;const run=cross;if(index>=run.entries.length){cross.active=false;cross.preparing=false;if(pad.crossOwned){pad.stop();pad.crossOwned=false;}notify('CrossMusic concluído.');render();return;}run.index=index;run.preparing=true;const entry=run.entries[index],project=projects.find(p=>p.id===entry.projectId);if(!project){cross.active=false;throw Error('Projeto do CrossMusic não encontrado.');}for(const t of project.tracks){const mix=entry.tracks[t.id];if(mix){t.db=mix.db;t.mute=mix.mute;}}project.loop=false;await DB.saveProject(project);await choose(project,true);if(!engine.ready){run.active=false;throw Error('Não foi possível preparar o projeto do CrossMusic.');}if(run.generation!==crossGeneration)return;try{if(entry.pad.enabled){const key=entry.pad.follow?keyParts(targetKey(project)):entry.pad;await pad.transition({note:key.note,minor:key.minor,volume:entry.pad.volume,sound:entry.pad.sound},3);pad.crossOwned=true;}else if(pad.crossOwned){pad.stop();pad.crossOwned=false;}await engine.play();run.preparing=false;render();}catch(e){run.active=false;throw e;}}
function endCross(){if(!confirm('Encerrar o CrossMusic? A música e o PAD atuais continuarão tocando.'))return;cross.active=false;pad.crossOwned=false;modal.close();render();}
async function outputDialog(){const c=await engine.context();show(head('Saída de áudio')+'<p>Web Audio oferece a saída estéreo do navegador. USB multicanal e execução em segundo plano dependem da plataforma e não são certificados.</p><button id="resumeAudio">ATUALIZAR / RETOMAR SAÍDA</button>'+(typeof c.setSinkId==='function'?'<button id="chooseOutput">ESCOLHER DISPOSITIVO</button>':'<p>A escolha de dispositivo é gerenciada pelo navegador/sistema nesta versão.</p>'));$('#resumeAudio').onclick=async()=>{await c.resume();if(p)await engine.rebuild();notify('Saída retomada.');};if($('#chooseOutput'))$('#chooseOutput').onclick=async()=>{try{if(!navigator.mediaDevices?.selectAudioOutput)throw Error('O navegador não oferece seleção de saída. Use as configurações do sistema.');const device=await navigator.mediaDevices.selectAudioOutput();await c.setSinkId(device.deviceId);notify('Saída atualizada.');}catch(e){fail(e);}};}


export {engine,rhythm,pad,rhythmLink};
export function currentProject(){return p;}

function searchProjects(){const keys=[...NOTES,...NOTES.map(n=>n+'m')];show(head('Pesquisar projetos')+'<input id="query" aria-label="Nome ou tom" placeholder="Nome do projeto ou tonalidade"><label>Tom exato<select id="keyFilter"><option value="">Todos</option>'+keys.map(n=>'<option>'+n+'</option>').join('')+'</select></label><div class="search-results" id="results"></div>');const run=()=>{const query=normalize($('#query').value),filter=keyParts($('#keyFilter').value);$('#results').innerHTML=projects.filter(project=>{const key=keyParts(targetKey(project));return (normalize(project.name).includes(query)||normalize(targetKey(project)).includes(query))&&(!filter||key&&key.note===filter.note&&key.minor===filter.minor);}).map(project=>'<button data-result="'+project.id+'">'+esc(project.name)+' · '+esc(targetKey(project)||'Sem tom')+'</button>').join('')||'<p>Nenhum projeto encontrado.</p>';listen('[data-result]','click',(_,el)=>{modal.close();choose(projects.find(p=>p.id===el.dataset.result));});};$('#query').oninput=run;$('#keyFilter').onchange=run;run();$('#query').focus();}$('#search').onclick=searchProjects;
